import { RESOURCES, RESOURCE_KEYS, FACTIONS } from './data.js';
import { tradingAccess } from './trade.js';
import { cargoCapacity, fleetTravelDays } from './fleets.js';
import { getPlanet } from './state.js';
import { esc,fmt,opts,button } from './ui-format.js';
export function circuitPlanets(state) {return state.planets.filter(p=>!p.destroyed&&(p.owner==='player'||tradingAccess(state,p)));}
export function defaultCircuit(state,p,target,amount=40,resource='ore') {
 return {interval:0,stops:[{planet:p.id,actions:[{kind:'unload',resource:'food',amount,reserve:0,minPrice:0,maxPrice:1000000},{kind:'load',resource,amount,reserve:40,minPrice:0,maxPrice:1000000}]},{planet:target.id,actions:target.owner==='player'?[{kind:'unload',resource,amount,reserve:0,minPrice:0,maxPrice:1000000}]:[{kind:'sell',resource,amount,reserve:0,minPrice:0,maxPrice:1000000},{kind:'buy',resource:'food',amount,reserve:0,minPrice:0,maxPrice:1000000}]}]};
}
export function circuitPanel(state,ui,p,selection) {
 const {ships,f,target}=selection,planets=circuitPlanets(state);
 if(!f||!target)return '<div class="alert">Für einen Handelskreislauf werden ein freier Frachter und ein zugänglicher zweiter Planet benötigt.</div>';
 const draft=ui.routeDraft??defaultCircuit(state,p,target,Math.min(40,cargoCapacity(state,f.type)),ui.cargo??'ore');
 const max=state.tech.includes('smartLogistics')?8:state.tech.includes('tradeCircuits')?6:2;
 let duration=0;for(let i=0;i<draft.stops.length;i++){const from=getPlanet(state,draft.stops[i].planet),to=getPlanet(state,draft.stops[(i+1)%draft.stops.length].planet);if(from&&to)duration+=fleetTravelDays(state,from,to,[f]);}
 return `<p class="lede">Jeder Stopp hat eigene Warenaufträge. Ein Frachtraum wird von allen Gütern gemeinsam genutzt. Nach dem letzten Stopp kehrt das Schiff zum ersten zurück.</p><label class="form-label">Frachter</label><select class="select" data-field="routeFleet">${opts(ships.map(s=>[s.id,`${s.name} · ${cargoCapacity(state,s.type)} Fracht`]),f.id)}</select><p class="note">Mindestens ${duration} Flugtage pro Umlauf, zuzüglich Versorgungspausen. Aktuell bis zu ${max} Stopps.</p>${draft.stops.map((stop,i)=>{
 const q=getPlanet(state,stop.planet),own=q?.owner==='player';
 return `<div class="detail-card route-stop"><div class="card-heading"><strong>Stopp ${i+1}${i===0?' · Heimathafen':''}</strong>${i>1?button('Entfernen','circuit-remove-stop',`data-index="${i}"`):''}</div><label class="form-label">Planet</label><select class="select" data-field="circuitPlanet:${i}" ${i===0?'disabled':''}>${opts(planets.map(q=>[q.id,`${q.name} · ${q.owner==='player'?'Eigene Kolonie':FACTIONS[q.owner].name}`]),stop.planet)}</select>${stop.actions.map((a,j)=>`<div class="route-action"><div class="two-column"><label class="form-label">Auftrag<select class="select" data-field="circuitKind:${i}:${j}">${opts(own?[['unload','Entladen'],['load','Laden']]:[['sell','Verkaufen'],['buy','Kaufen']],a.kind)}</select></label><label class="form-label">Ware<select class="select" data-field="circuitResource:${i}:${j}">${opts(RESOURCE_KEYS.map(k=>[k,RESOURCES[k].name]),a.resource)}</select></label><label class="form-label">Max. Menge<input class="text-input" type="number" min="1" max="${cargoCapacity(state,f.type)}" data-field="circuitAmount:${i}:${j}" value="${a.amount}"></label><label class="form-label">${a.kind==='load'?'Örtlicher Mindestbestand':a.kind==='sell'?'Mindestpreis ¢':a.kind==='buy'?'Höchstpreis ¢':'Entladen ohne Verkauf'}<input class="text-input" type="number" min="0" step="0.1" data-field="circuitLimit:${i}:${j}" value="${a.kind==='load'?a.reserve??0:a.kind==='sell'?a.minPrice??0:a.kind==='buy'&&a.maxPrice<1000000?a.maxPrice:0}" ${a.kind==='unload'?'disabled':''}></label></div>${button('Warenauftrag entfernen','circuit-remove-action',`data-index="${i}" data-order="${j}"`)}</div>`).join('')}${button('Warenauftrag hinzufügen','circuit-add-action',`data-index="${i}"`,stop.actions.length>=8)}</div>`;
 }).join('')}<label class="form-label">Mindestabstand zwischen Umläufen / Tage</label><input class="text-input" type="number" min="0" max="120" data-field="circuitInterval" value="${draft.interval}"><p class="note">0 = direkt weiterfahren. Größere Abstände können einen kleinen steten Bedarf bedienen. Unter den Versorgungsgrenzen wartet der Frachter auf Auffüllung; Einstellungen findest du im Flottenkommando.</p><div class="button-row">${button('Stopp hinzufügen','circuit-add-stop','',draft.stops.length>=max)}${button('Handelskreislauf starten','circuit-start')}</div>${max===2?'<p class="research-condition unmet">Mehr Stopps benötigen: Mehrstufige Handelskreisläufe.</p>':''}`;
}
